package com.secure.documentwallet;

import android.app.*;import android.content.*;import android.os.Bundle;import android.view.*;import android.widget.*;import androidx.fragment.app.FragmentActivity;import org.json.*;import java.text.*;import java.util.*;import java.util.concurrent.*;

/** Computes status from real local evidence instead of presenting a decorative security score. */
public class VaultHealthActivity extends FragmentActivity {
 private final ExecutorService io=Executors.newSingleThreadExecutor();private LinearLayout body;private TextView score,note;private ProgressBar progress;
 @Override public void onCreate(Bundle state){super.onCreate(state);Ui.safeScreen(this);Ui.lightBars(this);if(!Session.valid()){finish();return;}build();refresh();}
 private void build(){LinearLayout page=VaultPageUi.page(this);page.addView(VaultPageUi.header(this,"Security And Backup","Live vault protection status"));LinearLayout health=VaultPageUi.card(this);health.setBackground(Ui.stroke(0xffe4f6ef,Ui.dp(this,1),0xff9dd9c6,Ui.dp(this,18)));LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);top.addView(Ui.title(this,"Vault Health",16),new LinearLayout.LayoutParams(0,-2,1));score=Ui.title(this,"Checking…",16);score.setTextColor(0xff168365);top.addView(score);health.addView(top);progress=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);progress.setMax(100);progress.setProgressTintList(android.content.res.ColorStateList.valueOf(0xff168365));progress.setProgressBackgroundTintList(android.content.res.ColorStateList.valueOf(0xffbfe5d8));LinearLayout.LayoutParams pp=new LinearLayout.LayoutParams(-1,Ui.dp(this,7));pp.topMargin=Ui.dp(this,10);health.addView(progress,pp);note=Ui.text(this,"Checking local protection and backup evidence…",11,0xff168365);note.setPadding(0,Ui.dp(this,8),0,0);health.addView(note);LinearLayout.LayoutParams hp=new LinearLayout.LayoutParams(-1,-2);hp.topMargin=Ui.dp(this,4);page.addView(health,hp);page.addView(VaultPageUi.section(this,"Protection Status"));body=Ui.column(this);page.addView(body);TextView verify=VaultPageUi.primary(this,"Verify Local Vault");verify.setOnClickListener(v->verify());VaultPageUi.button(page,verify);TextView recovery=VaultPageUi.secondary(this,RecoveryKit.ready(this)?"Replace Recovery Code":"Create Recovery Code");recovery.setOnClickListener(v->createRecovery());VaultPageUi.button(page,recovery);TextView clear=VaultPageUi.secondary(this,"Clear Temporary Files");clear.setOnClickListener(v->{int n=SecureCache.clear(this);VaultActivityLog.add(this,"Temporary Files Cleared",n+" file"+(n==1?"":"s")+" removed");Ui.toast(this,n+" temporary file"+(n==1?"":"s")+" removed");refresh();});VaultPageUi.button(page,clear);setContentView(VaultPageUi.screen(this,page,"profile"));}
 private void refresh(){io.execute(()->{try{JSONArray docs=new VaultRepository(this).all();int expiring=0;long horizon=System.currentTimeMillis()+90L*86400000L;SimpleDateFormat format=new SimpleDateFormat("dd/MM/yyyy",Locale.US);format.setLenient(false);for(int i=0;i<docs.length();i++){String date=docs.getJSONObject(i).optString("expiryDate");if(!date.isEmpty())try{if(format.parse(date).getTime()<=horizon)expiring++;}catch(Exception ignored){}}SharedPreferences health=getSharedPreferences("vault-health",0);long backup=health.getLong("last_backup",0),verified=health.getLong("last_verified",0);int temp=SecureCache.count(this),value=0;if(VaultKeyManager.protectedByKeystore(this))value+=35;if(RecoveryKit.ready(this))value+=25;if(recent(backup,7))value+=20;if(recent(verified,30))value+=20;int finalExpiring=expiring,finalValue=value;runOnUiThread(()->render(docs.length(),finalExpiring,temp,backup,verified,finalValue));}catch(Exception e){runOnUiThread(()->Ui.toast(this,"Could Not Read Vault Health"));}});}
 private boolean recent(long when,int days){return when>0&&System.currentTimeMillis()-when<=days*86400000L;}
 private void render(int count,int expiring,int temp,long backup,long verified,int value){score.setText(value+"%");progress.setProgress(value);note.setText(value==100?"All tracked protections are current":value>=60?"Some protection needs attention":"Complete the items below before relying on this vault");body.removeAllViews();row("Encryption Key",VaultKeyManager.protectedByKeystore(this)?"Protected by Android Keystore":"Protection upgrade pending",VaultKeyManager.protectedByKeystore(this));row("Recovery Code",RecoveryKit.ready(this)?"Ready for a replacement phone":"Create and store a recovery code",RecoveryKit.ready(this));row("Encrypted Backup",backup==0?"No successful backup recorded":"Last backup: "+date(backup)+(recent(backup,7)?"":" · Needs refresh"),recent(backup,7));row("Backup Verification",verified==0?"Not verified yet":"Verified: "+date(verified)+(recent(verified,30)?"":" · Verify again"),recent(verified,30));row("Encrypted Documents",count+" saved",true);row("Expiry Attention",expiring==0?"Nothing due within 90 days":expiring+" due or expiring soon",expiring==0);row("Temporary Files",temp==0?"Clean":temp+" waiting for scheduled cleanup",temp==0);}
 private void row(String title,String value,boolean good){LinearLayout row=VaultPageUi.iconRow(this,good?"check":"info",title,value);VaultPageUi.addRow(body,row);}
 private String date(long value){return new SimpleDateFormat("dd/MM/yy · h:mm a",Locale.getDefault()).format(new Date(value));}
 private void verify(){ProgressDialog wait=new ProgressDialog(this);wait.setCancelable(false);wait.setMessage("Authenticating every encrypted vault object…");wait.show();io.execute(()->{try{int count=new VaultRepository(this).verifyAll();runOnUiThread(()->{wait.dismiss();VaultActivityLog.add(this,"Encrypted Vault Verified",count+" protected objects authenticated");Ui.toast(this,count+" encrypted objects verified");refresh();});}catch(Exception e){runOnUiThread(()->{wait.dismiss();new AlertDialog.Builder(this).setTitle("Vault Verification Failed").setMessage("One or more encrypted objects could not be authenticated. Make a fresh backup before changing anything.").setPositiveButton("OK",null).show();});}});}
 private void createRecovery(){try{String code=RecoveryKit.create(this);TextView value=Ui.text(this,code,19,Ui.NAVY);value.setTextIsSelectable(true);value.setGravity(Gravity.CENTER);value.setPadding(Ui.dp(this,18),Ui.dp(this,18),Ui.dp(this,18),Ui.dp(this,18));new AlertDialog.Builder(this).setTitle("Save Your Recovery Code").setMessage("Write this code down and keep it somewhere separate from your phone. It is required to restore My Vault on a replacement device and cannot be shown again.").setView(value).setPositiveButton("I Saved It",(d,w)->{VaultActivityLog.add(this,"Recovery Code Updated","Replacement phone access prepared");refresh();}).setCancelable(false).show();}catch(Exception e){Ui.toast(this,"Could Not Create The Recovery Code");}}
 @Override protected void onDestroy(){super.onDestroy();io.shutdownNow();}
}
